// 计算「上一个完整周」(Mon-Sun, Asia/Singapore) 以及它的前一周，用于周环比。
// 周一 09:00 触发时，上一个完整周 = 上周一 ~ 上周日。
const fmt = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Singapore', year: 'numeric', month: '2-digit', day: '2-digit',
});
const todaySGT = fmt.format(new Date());            // YYYY-MM-DD
const anchor = new Date(todaySGT + 'T00:00:00Z');   // 用 UTC 做纯日期运算，避开时区漂移

const dow = anchor.getUTCDay();                     // 0=Sun … 6=Sat
const daysSinceMonday = (dow + 6) % 7;

const thisMonday = new Date(anchor);
thisMonday.setUTCDate(anchor.getUTCDate() - daysSinceMonday);

const shift = (base, days) => {
  const d = new Date(base);
  d.setUTCDate(base.getUTCDate() + days);
  return d;
};
const iso = (d) => d.toISOString().slice(0, 10);

const since     = shift(thisMonday, -7);
const until     = shift(thisMonday, -1);
const prevSince = shift(thisMonday, -14);
const prevUntil = shift(thisMonday, -8);

return [{
  json: {
    since:     iso(since),
    until:     iso(until),
    prevSince: iso(prevSince),
    prevUntil: iso(prevUntil),
    label:     iso(since) + ' → ' + iso(until),
    generatedAt: new Date().toISOString(),
  },
}];

// 把两周的 Insights 响应压平成「每个 campaign 一行」，并算出周环比。
//
// 口径说明（重要，别混着算）:
//   onsite_conversion.lead_grouped   = 站内即时表单 (Lead Ads) 的 leads
//   offsite_conversion.fb_pixel_lead = 网站表单，靠 Pixel / CAPI 上报的 Lead 事件
//   lead                             = Meta 的聚合口径，可能已包含上面两者 —— 不要相加，
//                                      只单独留着做对账，否则会双重计数。
//   onsite_conversion.messaging_conversation_started_7d = Click-to-WhatsApp 的对话数，
//                                      不是 lead，单独看。

const CFG = $('Config').first().json;
const R   = $('Date Ranges').first().json;

const A_FORM  = 'onsite_conversion.lead_grouped';
const A_PIXEL = 'offsite_conversion.fb_pixel_lead';
const A_AGG   = 'lead';
const A_CTWA  = 'onsite_conversion.messaging_conversation_started_7d';

const act = (actions, type) => {
  if (!Array.isArray(actions)) return 0;
  const hit = actions.find((a) => a.action_type === type);
  return hit ? Number(hit.value) || 0 : 0;
};

const shape = (resp) => {
  const rows = (resp && Array.isArray(resp.data)) ? resp.data : [];
  const out = {};
  for (const r of rows) {
    const formLeads  = act(r.actions, A_FORM);
    const pixelLeads = act(r.actions, A_PIXEL);
    out[r.campaign_id] = {
      campaignId:   r.campaign_id,
      campaignName: r.campaign_name,
      spend:        Number(r.spend) || 0,
      impressions:  Number(r.impressions) || 0,
      clicks:       Number(r.clicks) || 0,
      formLeads,
      pixelLeads,
      leads:        formLeads + pixelLeads,
      leadsAggCheck: act(r.actions, A_AGG),   // 对账用，不参与求和
      ctwaChats:    act(r.actions, A_CTWA),
    };
  }
  return out;
};

const cur  = shape($('Insights - Last Week').first().json);
const prev = shape($('Insights - Previous Week').first().json);

const round2 = (n) => Math.round(n * 100) / 100;
const cpl = (spend, leads) => (leads > 0 ? round2(spend / leads) : null);

const items = Object.values(cur)
  // 完全没花钱也没曝光的，多半是当周没投放，剔掉免得噪音
  .filter((c) => c.spend > 0 || c.impressions > 0)
  .map((c) => {
    const p = prev[c.campaignId] || { leads: 0, spend: 0 };
    const curCpl  = cpl(c.spend, c.leads);
    const prevCpl = cpl(p.spend, p.leads);
    return {
      weekStart:      R.since,
      weekEnd:        R.until,
      campaignId:     c.campaignId,
      campaignName:   c.campaignName,
      spend:          round2(c.spend),
      currency:       CFG.currency,
      impressions:    c.impressions,
      clicks:         c.clicks,
      ctr:            c.impressions > 0 ? round2((c.clicks / c.impressions) * 100) : 0,
      leads:          c.leads,
      formLeads:      c.formLeads,
      pixelLeads:     c.pixelLeads,
      ctwaChats:      c.ctwaChats,
      cpl:            curCpl,
      prevLeads:      p.leads,
      leadsDelta:     c.leads - p.leads,
      prevCpl:        prevCpl,
      cplDeltaPct:    (prevCpl && curCpl) ? round2(((curCpl - prevCpl) / prevCpl) * 100) : null,
      leadsAggCheck:  c.leadsAggCheck,
      generatedAt:    R.generatedAt,
    };
  })
  .sort((a, b) => b.leads - a.leads || b.spend - a.spend);

if (items.length === 0) {
  return [{ json: {
    weekStart: R.since, weekEnd: R.until,
    campaignId: '', campaignName: '(本周无投放)',
    spend: 0, currency: CFG.currency, impressions: 0, clicks: 0, ctr: 0,
    leads: 0, formLeads: 0, pixelLeads: 0, ctwaChats: 0, cpl: null,
    prevLeads: 0, leadsDelta: 0, prevCpl: null, cplDeltaPct: null,
    leadsAggCheck: 0, generatedAt: R.generatedAt,
  }}];
}

return items.map((json) => ({ json }));

// 把所有 campaign 行折叠成一条 WhatsApp 消息。
// WhatsApp 支持 *粗体* _斜体_ ~删除线~ ```等宽```，不支持表格 —— 所以用缩进列表。

const CFG  = $('Config').first().json;
const R    = $('Date Ranges').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r.campaignId);

const cur  = CFG.currency;
const n2   = (x) => (x === null || x === undefined ? '—' : Number(x).toFixed(2));
const pct  = (x) => (x === null || x === undefined ? '' : (x > 0 ? '+' : '') + x.toFixed(0) + '%');
const delta = (d) => (d === 0 ? '➖ 持平' : `${d > 0 ? '🔺 +' : '🔻 '}${d}`);

if (rows.length === 0) {
  return [{ json: { message: `*📊 Meta Ads 周报*\n${R.label}\n\n本周无投放数据。` } }];
}

const T = rows.reduce((a, r) => ({
  leads:     a.leads + r.leads,
  prevLeads: a.prevLeads + r.prevLeads,
  spend:     a.spend + r.spend,
  ctwa:      a.ctwa + r.ctwaChats,
}), { leads: 0, prevLeads: 0, spend: 0, ctwa: 0 });

const totalCpl     = T.leads > 0 ? T.spend / T.leads : null;
const leadsDelta   = T.leads - T.prevLeads;
const leadsPctText = T.prevLeads > 0 ? ` (${pct((leadsDelta / T.prevLeads) * 100)})` : '';

const TOP = 8;
const shown = rows.slice(0, TOP);
const rest  = rows.slice(TOP);

const lines = [
  `*📊 Meta Ads 周报*`,
  `_${R.label}_`,
  ``,
  `*${T.leads}* leads  ${delta(leadsDelta)}${leadsPctText}`,
  `花费 ${cur} ${n2(T.spend)}  ·  CPL ${cur} ${n2(totalCpl)}`,
];

if (T.ctwa > 0) lines.push(`WhatsApp 对话 ${T.ctwa} 次`);

lines.push(``, `*Campaign 明细*`);

shown.forEach((r, i) => {
  const d = r.leadsDelta;
  const cplTag = r.cplDeltaPct === null ? '' : `  (CPL ${pct(r.cplDeltaPct)})`;
  lines.push(
    `${i + 1}. ${r.campaignName}`,
    `    ${r.leads} leads ${delta(d)}  ·  ${cur} ${n2(r.spend)}  ·  CPL ${cur} ${n2(r.cpl)}${cplTag}`,
  );
});

if (rest.length > 0) {
  const restLeads = rest.reduce((a, r) => a + r.leads, 0);
  const restSpend = rest.reduce((a, r) => a + r.spend, 0);
  lines.push(`   _其余 ${rest.length} 个 campaign：${restLeads} leads · ${cur} ${n2(restSpend)}_`);
}

// 一条 WhatsApp 文本上限约 65k 字符，但手机端超过 ~1500 就要点「阅读更多」，截断更实用
let message = lines.join('\n');
if (message.length > 3500) message = message.slice(0, 3450) + '\n…（已截断，完整数据见 Google Sheet）';

if (CFG.reportLink) message += `\n\n完整报表 → ${CFG.reportLink}`;

return [{ json: { message, campaignCount: rows.length, totalLeads: T.leads } }];
